// ANTES: una clase con tres jefes
const redondear = (n) => Math.round(n); // helper compartido: a pesos enteros

class Despacho {
  constructor(kg, km, servicio) { this.kg = kg; this.km = km; this.servicio = servicio; }
  tarifa() {                                   // Finanzas
    return redondear(1200 + this.km * 8.5 + this.kg * 41.3);
  }
  remito() {                                   // Depósito / operaciones
    return `REMITO | ${this.kg} kg | ${this.km} km | total $ ${redondear(this.tarifa())}`;
  }
  guardar(tabla) {                             // Sistemas
    tabla.push({ kg: this.kg, km: this.km, total: this.tarifa() });
  }
}

const tabla = [];
const d = new Despacho(18, 42, "estandar");
console.log("tarifa :", d.tarifa());
console.log("remito :", d.remito());
d.guardar(tabla);
console.log("guardado:", JSON.stringify(tabla));

// Sigue el pedido de Depósito: «el remito tiene que mostrar centavos».
// Alguien toca el helper compartido, que es lo más rápido:
const redondear = (n) => Math.round(n * 100) / 100;

class Despacho {
  constructor(kg, km) { this.kg = kg; this.km = km; }
  tarifa() { return redondear(1200 + this.km * 8.5 + this.kg * 41.3); }
  remito() { return `REMITO | ${this.kg} kg | ${this.km} km | total $ ${redondear(this.tarifa())}`; }
}
const d = new Despacho(18, 42);
console.log("tarifa :", d.tarifa(), " <- Finanzas facturaba 2301 y ahora sale esto");
console.log("remito :", d.remito());

// DESPUÉS: cada función responde a un solo pedido de cambio
// Finanzas decide esto:
const tarifa = ({ kg, km }) => Math.round(1200 + km * 8.5 + kg * 41.3);
// Operaciones decide esto (y ahora pidió centavos):
const remito = ({ kg, km }, total) =>
  `REMITO | ${kg} kg | ${km} km | total $ ${total.toFixed(2)}`;
// Sistemas decide esto:
const guardar = (tabla, envio, total) => tabla.push({ ...envio, total });

const envio = { kg: 18, km: 42 };
const tabla = [];
const total = tarifa(envio);
console.log("tarifa :", total);
console.log("remito :", remito(envio, total));
guardar(tabla, envio, total);
console.log("guardado:", JSON.stringify(tabla));

// ANTES: una función que hay que abrir cada vez que aparece un servicio nuevo
function cotizar(envio) {
  const base = 1200 + envio.km * 8.5 + envio.kg * 41.3;
  if (envio.servicio === "estandar") return Math.round(base);
  if (envio.servicio === "express") return Math.round(base * 1.6);
  if (envio.servicio === "refrigerado") return Math.round(base * 1.35 + 900);
  throw new Error("servicio desconocido: " + envio.servicio);
}
console.log(cotizar({ kg: 18, km: 42, servicio: "estandar" }));
console.log(cotizar({ kg: 18, km: 42, servicio: "express" }));
console.log(cotizar({ kg: 18, km: 42, servicio: "refrigerado" }));

// DESPUÉS: cotizar queda cerrada; las reglas son una tabla que se extiende
const base = ({ kg, km }) => 1200 + km * 8.5 + kg * 41.3;

const reglas = {
  estandar:    (e) => Math.round(base(e)),
  express:     (e) => Math.round(base(e) * 1.6),
  refrigerado: (e) => Math.round(base(e) * 1.35 + 900),
};

function cotizar(envio, reglas) {
  const regla = reglas[envio.servicio];
  if (!regla) throw new Error("servicio desconocido: " + envio.servicio);
  return regla(envio);
}

const e = { kg: 18, km: 42 };
for (const s of ["estandar", "express", "refrigerado"]) {
  console.log(s.padEnd(12), cotizar({ ...e, servicio: s }, reglas));
}

// Llega «frágil»: se agrega una regla, cotizar no se toca
const conFragil = { ...reglas, fragil: (e) => Math.round(base(e) + 450 + e.kg * 12) };
console.log("fragil".padEnd(12), cotizar({ ...e, servicio: "fragil" }, conFragil));

// Lo que se paga: un error nuevo posible
try { cotizar({ ...e, servicio: "frágil" }, conFragil); }   // con tilde
catch (err) { console.log("error:", err.message); }

// El mismo cálculo, «bien separado» sin motivo: seis piezas para una cuenta
class ConstanteBase { valor() { return 1200; } }
class CostoPorKm { constructor(k) { this.k = k; } valor() { return this.k * 8.5; } }
class CostoPorKg { constructor(k) { this.k = k; } valor() { return this.k * 41.3; } }
class Sumador { sumar(...partes) { return partes.reduce((a, p) => a + p.valor(), 0); } }
class Redondeador { redondear(n) { return Math.round(n); } }
class FabricaDeTarifa {
  crear({ kg, km }) {
    return new CalculadorDeTarifa(new Sumador(), new Redondeador(),
      [new ConstanteBase(), new CostoPorKm(km), new CostoPorKg(kg)]);
  }
}
class CalculadorDeTarifa {
  constructor(s, r, partes) { this.s = s; this.r = r; this.partes = partes; }
  calcular() { return this.r.redondear(this.s.sumar(...this.partes)); }
}
console.log(new FabricaDeTarifa().crear({ kg: 18, km: 42 }).calcular());
